        assert((y16 as int + z16 as int) >= i16::MIN as int);
        let sum_yz: i16 = y16 + z16;

        assert((x16 as int + z16 as int) <= i16::MAX as int);
        assert((x16 as int + z16 as int) >= i16::MIN as int);
        let sum_xz: i16 = x16 + z16;

